  const url = String(input);
  if (!url.startsWith("https://api.github.com/")) return realFetch(input, init);
  calls++;
  if (/\/git\/trees\//.test(url)) {
    const r = await realFetch(url, { headers: { Authorization: `Bearer ${env.GITHUB_TOKEN}` } });
