export const CAPTURE_LIMITS = {
  requestTimeoutMs: 15000,
  observationRunMs: 25000,
  checkpointRefs: 100,
  archiveBytes: 50 * 1024 * 1024,
  expandedBytes: 250 * 1024 * 1024,
  archiveFiles: 50000,
  repairSeconds: 300,
} as const;
export function observationInterval(
  deadline: string,
  now = Date.now(),
): number {
  return new Date(deadline).getTime() - now <= 10 * 60_000 ? 60 : 300;
}
export function frozenRepositoryLink(
  r: Pick<RepositoryCapture, "fork_url" | "frozen_sha" | "snapshot_state">,
): string | null {
  return r.snapshot_state === "ready" && r.fork_url && r.frozen_sha
    ? `${r.fork_url}/tree/${r.frozen_sha}`
