}
export function strictRepository(url: string): { owner: string; repo: string } {
  const match =
    /^https:\/\/github\.com\/([A-Za-z0-9_.-]+)\/([A-Za-z0-9_.-]+)\/?$/.exec(
      url,
    );
  if (!match) throw new Error("Invalid GitHub repository URL");
  return { owner: match[1], repo: match[2].replace(/\.git$/, "") };
}
import { createHash } from "node:crypto";
import type { SupabaseClient } from "@supabase/supabase-js";
import { CAPTURE_LIMITS } from "./types";

export class GitHubFailure extends Error {
  constructor(
    message: string,
    public readonly kind: "transient" | "access" | "configuration",
    public readonly retrySeconds = 60,
    public readonly status?: number,
  ) {
    super(message);
  }
}
export function safeGitHubMessage(message: string): string {
  return message
    .replace(
      /(?:gh[pousr]_[A-Za-z0-9_]+|github_pat_[A-Za-z0-9_]+|Bearer\s+\S+|token\s+\S+)/gi,
      "[redacted]",
    )
    .replace(/https?:\/\/\S+/g, "[url]")
    .slice(0, 300);
}
export function classifyGitHub(
  status: number,
  headers: Headers,
  message: string,
): GitHubFailure {
  const remaining = headers.get("x-ratelimit-remaining");
  const retry = Number(headers.get("retry-after"));
  const reset = Number(headers.get("x-ratelimit-reset")) * 1000;
  const delay =
    retry > 0
      ? retry
      : remaining === "0" && reset > Date.now()
        ? Math.ceil((reset - Date.now()) / 1000)
        : 60;
  const kind =
    status === 429 ||
    status >= 500 ||
    (status === 403 &&
      (remaining === "0" || retry > 0 || /rate limit|abuse/i.test(message)))
      ? "transient"
      : status === 401 || status === 403
        ? "configuration"
        : "access";
  return new GitHubFailure(
    safeGitHubMessage(message || `GitHub HTTP ${status}`),
    kind,
    delay,
    status,
  );
}
const identities = new Map<string, string>();
export class CaptureGitHub {
  private identity: string | undefined;
  constructor(
    private db: SupabaseClient,
    private token: string,
    private repositoryId?: string,
  ) {}
  async initialize() {
    if (!this.token)
      throw new GitHubFailure(
        "GitHub credentials are not configured",
        "configuration",
      );
    const fingerprint = createHash("sha256").update(this.token).digest("hex");
    this.identity = identities.get(fingerprint);
    if (this.identity) return;
    // One identity lookup per credential/process; subsequent operations share the account budget.
    const res = await fetch("https://api.github.com/user", {
      headers: this.headers(),
      signal: AbortSignal.timeout(CAPTURE_LIMITS.requestTimeoutMs),
      cache: "no-store",
    });
    if (!res.ok)
      throw classifyGitHub(res.status, res.headers, await res.text());
    const user = await res.json();
    if (!Number.isSafeInteger(user.id))
      throw new GitHubFailure(
        "GitHub credential identity unavailable",
        "configuration",
      );
    this.identity = `user:${user.id}`;
    identities.set(fingerprint, this.identity);
  }
  private headers() {
    return {
      Authorization: `Bearer ${this.token}`,
      Accept: "application/vnd.github+json",
      "Content-Type": "application/json",
      "User-Agent": "submission-worker",
    };
  }
  async request(
    path: string,
    method = "GET",
    body?: unknown,
    essential = false,
  ): Promise<Response> {
    await this.initialize();
    const url = new URL(path, "https://api.github.com");
    if (url.origin !== "https://api.github.com")
      throw new Error("Unexpected GitHub API origin");
    const { data: permit, error } = await this.db.rpc(
      "reserve_github_request",
      {
        p_identity: this.identity,
        p_write: method !== "GET",
        p_essential: essential,
      },
    );
    if (error)
      throw new GitHubFailure("Request budget unavailable", "transient");
    if (permit.delay)
      throw new GitHubFailure(
        "GitHub work paused to preserve request capacity",
        "transient",
        permit.delay,
      );
    try {
      const res = await fetch(url, {
        method,
        headers: this.headers(),
        body: body === undefined ? undefined : JSON.stringify(body),
        signal: AbortSignal.timeout(CAPTURE_LIMITS.requestTimeoutMs),
        cache: "no-store",
        redirect: "manual",
      });
      const remaining = res.headers.get("x-ratelimit-remaining");
      const reset = res.headers.get("x-ratelimit-reset");
      const update: Record<string, unknown> = {};
      if (remaining !== null) update.remaining = Number(remaining);
      if (reset) update.reset_at = new Date(Number(reset) * 1000).toISOString();
      if (!res.ok && res.status !== 302) {
        let message = "";
        try {
          message = String((await res.clone().json()).message ?? "");
        } catch {
          message = `GitHub HTTP ${res.status}`;
        }
        const failure = classifyGitHub(res.status, res.headers, message);
        if (failure.kind !== "access")
          update.pause_until = new Date(
            Date.now() + failure.retrySeconds * 1000,
          ).toISOString();
        const { error: logError } = await this.db
          .from("github_request_failures")
          .insert({
            identity: this.identity,
            operation: `${method} ${url.pathname.replace(/\/repos\/[^/]+\/[^/]+/, "/repos/{repository}")}`,
            repository_id: this.repositoryId ?? null,
            status: res.status,
            message: failure.message,
            request_id: res.headers.get("x-github-request-id"),
            remaining: remaining === null ? null : Number(remaining),
            reset_at: update.reset_at ?? null,
            retry_after: failure.retrySeconds,
          });
        if (logError)
          console.error("Could not persist GitHub diagnostic", logError.code);
      }
      if (Object.keys(update).length)
        await this.db
          .from("github_request_budgets")
          .update(update)
          .eq("identity", this.identity);
      return res;
    } catch (error) {
      if (error instanceof GitHubFailure) throw error;
      await this.db
        .from("github_request_failures")
        .insert({
          identity: this.identity,
          operation: method,
          repository_id: this.repositoryId ?? null,
          message: "GitHub connection timed out or failed",
        });
      throw new GitHubFailure(
        "GitHub connection timed out or failed",
        "transient",
      );
    } finally {
      await this.db.from("github_request_slots").delete().eq("id", permit.slot);
    }
  }
  async json<T = Record<string, unknown>>(
    path: string,
    method = "GET",
    body?: unknown,
  ): Promise<T> {
    const res = await this.request(path, method, body);
    if (!res.ok) {
      let message = "";
      try {
        message = String((await res.json()).message ?? "");
      } catch {
        /* no JSON response */
      }
      throw classifyGitHub(res.status, res.headers, message);
    }
    return res.status === 204 ? (undefined as T) : ((await res.json()) as T);
  }
}

import { execFile } from "node:child_process";
import { promisify } from "node:util";
import { mkdtemp, writeFile, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { GitHubFailure } from "./github-client";
import { strictRepository, type RepositoryCapture } from "./types";
import {
  isPromptFilePath,
  isTranscriptFilePath,
  countPromptsInPromptTxt,
  promptCountFromMetadata,
} from "@/lib/entire";
const exec = promisify(execFile);

/** Bare Git only: never checks out or runs submitted files, hooks or dependencies. */
export async function transferCapturedRepository(
  r: RepositoryCapture,
  token: string,
  heartbeat: () => Promise<void>,
) {
  if (!r.frozen_sha || !/^[a-f0-9]{40}$/.test(r.frozen_sha) || !r.fork_url)
    throw new Error("Missing immutable capture");
  strictRepository(r.repo_url);
  strictRepository(r.fork_url);
  const directory = await mkdtemp(join(tmpdir(), "ehl-capture-"));
  const askpass = join(directory, "askpass.sh");
  await writeFile(
    askpass,
    '#!/bin/sh\ncase "$1" in *Username*) printf "%s\\n" x-access-token ;; *) printf "%s\\n" "$EHL_CAPTURE_GIT_TOKEN" ;; esac\n',
    { mode: 0o700 },
  );
  const env = {
    ...process.env,
    GIT_TERMINAL_PROMPT: "0",
    GIT_ASKPASS: askpass,
    EHL_CAPTURE_GIT_TOKEN: token,
    GIT_CONFIG_COUNT: "3",
    GIT_CONFIG_KEY_0: "core.hooksPath",
    GIT_CONFIG_VALUE_0: "/dev/null",
    GIT_CONFIG_KEY_1: "protocol.file.allow",
    GIT_CONFIG_VALUE_1: "never",
    GIT_CONFIG_KEY_2: "credential.helper",
    GIT_CONFIG_VALUE_2: "",
  };
  const git = async (...args: string[]) => {
    await heartbeat();
    try {
      return (
        await exec("git", args, {
          cwd: directory,
          env,
          timeout: 60000,
          maxBuffer: 16 * 1024 * 1024,
        })
      ).stdout;
    } catch {
      throw new GitHubFailure(
        "Could not transfer the frozen Git objects; retry scheduled",
        "transient",
      );
    }
  };
  try {
    await git("init", "--bare", ".");
    const shas = [
      ...new Set([r.frozen_sha, ...r.checkpoint_manifest.map((c) => c.sha)]),
    ];
    if (shas.some((sha) => !/^[a-f0-9]{40}$/.test(sha)))
      throw new Error("Invalid frozen checkpoint");
    await git("fetch", "--no-tags", "--depth=1", `${r.repo_url}.git`, ...shas);
    const resolved = (
      await git("rev-parse", `${r.frozen_sha}^{commit}`)
    ).trim();
    if (resolved !== r.frozen_sha) throw new Error("Frozen commit mismatch");
    if (r.entire_required) {
      let hasSession = false;
      for (const checkpoint of r.checkpoint_manifest) {
        const paths = (
          await git("ls-tree", "-r", "--name-only", checkpoint.sha)
        )
          .trim()
          .split("\n");
        if (paths.some(isTranscriptFilePath)) {
          hasSession = true;
          break;
        }
        for (const path of paths
          .filter((p) => isPromptFilePath(p) || /(^|\/)metadata\.json$/.test(p))
          .slice(0, 10)) {
          const text = await git("show", `${checkpoint.sha}:${path}`);
          try {
            if (
              isPromptFilePath(path)
                ? countPromptsInPromptTxt(text) > 0
                : promptCountFromMetadata(JSON.parse(text)) > 0
            )
              hasSession = true;
          } catch {
            /* malformed metadata is not proof of a session */
          }
        }
        if (hasSession) break;
      }
      if (!hasSession)
        throw new GitHubFailure(
          "No usable session evidence in the frozen checkpoint manifest",
          "access",
        );
    }
    const refs = [`${r.frozen_sha}:refs/heads/ehl-final/${r.revision}`];
    for (const checkpoint of r.checkpoint_manifest) {
      if (
        !/^refs\/(?:entire\/checkpoints\/[A-Za-z0-9_./-]+|heads\/entire\/checkpoints\/v1)$/.test(
          checkpoint.ref,
        )
      )
        throw new Error("Invalid checkpoint reference");
      refs.push(`${checkpoint.sha}:${checkpoint.ref}`);
    }
    await git("push", "--atomic", `${r.fork_url}.git`, ...refs);
  } finally {
    await rm(directory, { recursive: true, force: true });
  }
}
import { unzipSync } from "fflate";
import { CAPTURE_LIMITS } from "./types";
import type { CaptureGitHub } from "./github-client";
import { strictRepository } from "./types";

export function readRepositoryZip(bytes: Uint8Array): Map<string, string> {
  if (bytes.byteLength > CAPTURE_LIMITS.archiveBytes)
    throw new Error("Repository archive exceeds download limit");
  let expanded = 0,
    count = 0;
  const paths = new Set<string>();
  const archive = unzipSync(bytes, {
    filter: (file) => {
      count++;
      expanded += file.originalSize;
      if (
        count > CAPTURE_LIMITS.archiveFiles ||
        expanded > CAPTURE_LIMITS.expandedBytes
      )
        throw new Error("Repository archive exceeds expansion limit");
      const segments = file.name.split("/");
      if (
        file.name.startsWith("/") ||
        segments.includes("..") ||
        file.name.includes("\\") ||
        /[\x00-\x1f]/.test(file.name)
      )
        throw new Error("Unsafe archive path");
      const path = segments.slice(1).join("/");
      if (paths.has(path)) throw new Error("Duplicate archive path");
      paths.add(path);
      // Reviews historically omit files larger than 50 KB. Never extract to disk.
      return !file.name.endsWith("/") && file.originalSize <= 50000;
    },
  });
  const files = new Map<string, string>();
  for (const [name, bytes] of Object.entries(archive)) {
    const path = name.split("/").slice(1).join("/");
    if (path && !bytes.includes(0))
      files.set(path, new TextDecoder().decode(bytes));
  }
  return files;
}

export async function downloadCapturedArchive(
  github: CaptureGitHub,
  repoUrl: string,
  sha: string,
): Promise<Map<string, string>> {
  if (!/^[a-f0-9]{40}$/.test(sha))
    throw new Error("An exact commit SHA is required");
  const { owner, repo } = strictRepository(repoUrl);
  let response = await github.request(`/repos/${owner}/${repo}/zipball/${sha}`);
  if (response.status === 302) {
    const location = new URL(response.headers.get("location") ?? "");
    if (
      location.protocol !== "https:" ||
      location.hostname !== "codeload.github.com"
    )
      throw new Error("Unexpected archive redirect");
    // Signed archive URL: never forward the API Authorization header.
    response = await fetch(location, {
      redirect: "error",
      signal: AbortSignal.timeout(60000),
      cache: "no-store",
    });
  }
  if (!response.ok || !response.body)
    throw new Error("Could not download frozen repository archive");
  const reader = response.body.getReader();
  const chunks: Uint8Array[] = [];
  let size = 0;
  try {
    for (;;) {
      const { done, value } = await reader.read();
      if (done) break;
      size += value.byteLength;
      if (size > CAPTURE_LIMITS.archiveBytes)
        throw new Error("Repository archive exceeds download limit");
      chunks.push(value);
    }
  } finally {
    await reader.cancel();
  }
  const bytes = new Uint8Array(size);
  let offset = 0;
  for (const chunk of chunks) {
    bytes.set(chunk, offset);
    offset += chunk.byteLength;
  }
  return readRepositoryZip(bytes);
}

import { createHash } from "node:crypto";
import type { SupabaseClient } from "@supabase/supabase-js";
import type { CapturedRepository } from "./types";
import { CaptureGitHub } from "./github-client";
import { downloadCapturedArchive } from "./archive";
import { ingestRepo, type IngestedRepo } from "@/lib/code-review/ingest";
import { captureCredentials } from "./server";
import {
  isPromptFilePath,
  promptCountFromMetadata,
  type SessionHistoryIngest,
} from "@/lib/entire";

export function sessionFromFiles(
  files: Map<string, string>,
  sha: string,
  checkpoints: number,
): SessionHistoryIngest {
  const session: SessionHistoryIngest = {
    resolvedRef: sha,
    checkpointCount: checkpoints,
    promptCount: 0,
    promptSamples: [],
    agentsDetected: [],
    filesTouched: [],
    signed: false,
    notes: [
      "Immutable checkpoint sample. Signature verification was not performed.",
    ],
  };
  for (const [path, text] of files) {
    if (isPromptFilePath(path)) {
      const prompts = text
        .split("\n\n---\n\n")
        .map((p) => p.trim())
        .filter(Boolean);
      session.promptCount += prompts.length;
      session.promptSamples.push(
        ...prompts
          .slice(0, Math.max(0, 40 - session.promptSamples.length))
          .map((p) => p.slice(0, 4000)),
      );
    } else if (/(^|\/)metadata\.json$/.test(path)) {
      try {
        const meta = JSON.parse(text);
        session.promptCount = Math.max(
          session.promptCount,
          promptCountFromMetadata(meta),
        );
        for (const key of ["agent", "Agent", "agent_type"])
          if (typeof meta[key] === "string")
            session.agentsDetected.push(meta[key]);
        for (const key of ["files_touched", "filesTouched", "files"])
          if (Array.isArray(meta[key]))
            session.filesTouched.push(
              ...meta[key]
                .filter((v: unknown) => typeof v === "string")
                .slice(0, 200),
            );
      } catch {
        /* malformed optional metadata */
      }
    }
  }
  session.agentsDetected = [...new Set(session.agentsDetected)];
  session.filesTouched = [...new Set(session.filesTouched)].slice(0, 200);
  return session;
}
export async function capturedReviewInput(
  db: SupabaseClient,
  repositories: CapturedRepository[],
  tokenBudget = 50000,
): Promise<{ input: IngestedRepo; session: SessionHistoryIngest | null }> {
  if (!repositories.length) throw new Error("No frozen repositories");
  const cacheKey = createHash("sha256")
    .update(JSON.stringify({ repositories, tokenBudget, version: 1 }))
    .digest("hex");
  const cached = await db
    .from("submission_review_inputs")
    .select("input")
    .eq("cache_key", cacheKey)
    .maybeSingle();
  if (cached.error) throw new Error("Cannot read captured review cache");
  if (cached.data) return cached.data.input;
  const { token } = await captureCredentials();
  const github = new CaptureGitHub(db, token);
  const contents = new Map<string, string>();
  let session: SessionHistoryIngest | null = null;
  for (const repository of repositories) {
    const files = await downloadCapturedArchive(
      github,
      repository.repoUrl,
      repository.commitSha,
    );
    for (const [path, content] of files)
      contents.set(
        repositories.length === 1 ? path : `${repository.fieldKey}/${path}`,
        content,
      );
    // Bound the advisory session sample separately from the complete captured manifest.
    for (const checkpoint of repository.checkpoints.slice(0, 10)) {
      if (session && session.promptSamples.length >= 40) break;
      const sample = sessionFromFiles(
        await downloadCapturedArchive(
          github,
          repository.repoUrl,
          checkpoint.sha,
        ),
        checkpoint.sha,
        repository.checkpoints.length,
      );
      if (!session) session = sample;
      else {
        session.promptCount += sample.promptCount;
        session.promptSamples.push(
          ...sample.promptSamples.slice(0, 40 - session.promptSamples.length),
        );
        session.agentsDetected = [
          ...new Set([...session.agentsDetected, ...sample.agentsDetected]),
        ];
        session.filesTouched = [
          ...new Set([...session.filesTouched, ...sample.filesTouched]),
        ].slice(0, 200);
      }
    }
  }
  const input = await ingestRepo(repositories[0].repoUrl, tokenBudget, {
    sha: repositories[0].commitSha,
    files: contents,
  });
  const result = { input, session };
  const { error } = await db
    .from("submission_review_inputs")
    .upsert({ cache_key: cacheKey, input: result });
  if (error) throw new Error("Could not persist captured review input");
  return result;
}
import type { SupabaseClient } from "@supabase/supabase-js";
import { getSettingValue, SETTING_KEYS } from "@/lib/settings";
import { CaptureGitHub } from "./github-client";
import { isDevLoginEnabled } from "@/lib/dev-login";

export async function captureCredentials() {
  return {
    token:
