      )) ?? "",
  };
}
export async function dispatchCaptureWorker(db: SupabaseClient, token: string) {
  const repository = process.env.GITHUB_REPO;
  if (!repository || !/^[\w.-]+\/[\w.-]+$/.test(repository))
    throw new Error("GITHUB_REPO is not configured");
  const github = new CaptureGitHub(db, token);
  await github.json(`/repos/${repository}/dispatches`, "POST", {
    event_type: isDevLoginEnabled()
      ? "process-submission-captures-test"
      : "process-submission-captures",
  });
}
import type { SupabaseClient } from "@supabase/supabase-js";
export async function reliableSubmissionsEnabled(
  db: SupabaseClient,
  challengeId: string,
) {
  const { data, error } = await db.rpc("submission_capture_enabled", {
    p_challenge: challengeId,
  });
  if (error) {
    // Safe rolling deployment: an unapplied feature migration means disabled.
    if (error.code === "PGRST202") return false;
    throw new Error("Could not determine submission processing mode");
  }
  return data === true;
}
export function validSubmissionInput(
  fields: unknown,
  stack: unknown,
): fields is Record<string, string> {
  return (
    !!fields &&
    typeof fields === "object" &&
    !Array.isArray(fields) &&
    Object.values(fields).every(
      (v) => typeof v === "string" && v.length <= 10000,
    ) &&
    Array.isArray(stack) &&
    stack.length <= 30 &&
    stack.every((v) => typeof v === "string" && v.length <= 100)
  );
}
import type { SupabaseClient } from "@supabase/supabase-js";
import type { Submission } from "@/lib/types";
import type { RepositoryCapture } from "./types";
import { frozenRepositoryLink } from "./types";
import { QUERY_LIMITS } from "@/lib/config/limits";
export async function withRepositoryCaptures(
  db: SupabaseClient,
  submissions: Submission[],
): Promise<Submission[]> {
  const active = submissions.filter((s) => s.processingVersion === 1);
  if (!active.length) return submissions;
  const { data, error } = await db
    .from("submission_repositories")
    .select("*")
    .in("team_id", [...new Set(active.map((s) => s.teamId))])
    .in("challenge_id", [...new Set(active.map((s) => s.challengeId))])
    .limit(QUERY_LIMITS.submissionProcessingJobs);
  if (error || (data?.length ?? 0) >= QUERY_LIMITS.submissionProcessingJobs)
    throw new Error(
      "Repository capture list is unavailable or reached its limit. Narrow the event selection.",
    );
  return submissions.map((s) => ({
    ...s,
    repositories: (data ?? []).filter(
      (r) => r.challenge_id === s.challengeId && r.team_id === s.teamId,
    ) as RepositoryCapture[],
  }));
}
export function submissionRepositoryLink(
  s: Submission,
  fieldKey: string,
  original: string,
): string | null {
  if (s.processingVersion !== 1) return s.forkUrl || original;
  const repository = s.repositories?.find((r) => r.field_key === fieldKey);
  return repository ? frozenRepositoryLink(repository) : null;
}

