import { NextResponse } from "next/server";
import { createClient } from "@/lib/supabase/server";
import { reliableSubmissionsEnabled } from "@/lib/submission-processing/participant";
import { checkRateLimit, apiLimiter } from "@/lib/ratelimit";
import { QUERY_LIMITS } from "@/lib/config/limits";
const uuid = /^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/i;
export async function GET(request: Request) {
  const db = await createClient();
  const {
    data: { user },
  } = await db.auth.getUser();
  if (!user)
    return NextResponse.json({ error: "Not authenticated" }, { status: 401 });
  const params = new URL(request.url).searchParams;
  const challenge = params.get("challengeId") ?? "",
    team = params.get("teamId") ?? "";
  if (!uuid.test(challenge) || !uuid.test(team))
    return NextResponse.json(
      { error: "Invalid team or challenge" },
      { status: 400 },
    );
  const reliable = await reliableSubmissionsEnabled(db, challenge);
  if (!reliable)
    return NextResponse.json({ reliable: false, repositories: [] });
  const limit = QUERY_LIMITS.submissionRepositories;
  const { data, error } = await db
    .from("submission_repositories")
    .select("*")
    .eq("challenge_id", challenge)
    .eq("team_id", team)
    .limit(limit);
  if (error)
    return NextResponse.json(
      { error: "Cannot read repository status" },
      { status: 500 },
    );
  return NextResponse.json({
    reliable,
    repositories: data ?? [],
    limited: (data?.length ?? 0) >= limit,
  });
}
export async function POST(request: Request) {
  const db = await createClient();
  const {
    data: { user },
  } = await db.auth.getUser();
  if (!user)
    return NextResponse.json({ error: "Not authenticated" }, { status: 401 });
  const rate = await checkRateLimit(apiLimiter, user.id);
  if (rate.limited)
    return NextResponse.json({ error: rate.error }, { status: 429 });
  let body;
  try {
    body = await request.json();
  } catch {
    return NextResponse.json({ error: "Invalid request" }, { status: 400 });
  }
  if (!body || typeof body !== "object" || Array.isArray(body))
    return NextResponse.json({ error: "Invalid request" }, { status: 400 });
  const { challengeId, teamId, fieldKey, repoUrl, branch = "" } = body;
  if (
    typeof challengeId !== "string" ||
    !uuid.test(challengeId) ||
    typeof teamId !== "string" ||
    !uuid.test(teamId) ||
    typeof fieldKey !== "string" ||
    fieldKey.length > 100 ||
    typeof repoUrl !== "string" ||
    repoUrl.length > 300 ||
    typeof branch !== "string" ||
    branch.length > 200
  )
    return NextResponse.json(
      { error: "Invalid repository request" },
      { status: 400 },
    );
  const { data, error } = await db.rpc("bind_submission_repository", {
    p_challenge: challengeId,
    p_team: teamId,
    p_field: fieldKey,
    p_url: repoUrl,
    p_branch: branch,
  });
  if (error)
    return NextResponse.json({ error: error.message }, { status: 400 });
  return NextResponse.json({ id: data, pending: true });
}
"use server";
import { requireAdminAction } from "@/lib/admin-auth";
import { createAdminClient } from "@/lib/supabase/admin";
import { revalidatePath } from "next/cache";
import { getSession } from "@/lib/actions/auth";
import { logEventStrict } from "@/lib/event-log";

export async function setReliableSubmissions(form: FormData) {
  const denied = await requireAdminAction();
  if (denied) throw new Error(denied);
  const id = String(form.get("chapterId") ?? "");
  if (!/^[a-f0-9-]{36}$/i.test(id)) throw new Error("Invalid chapter");
  const { error } = await createAdminClient()
    .from("chapters")
    .update({ reliable_submissions: form.get("enabled") === "true" })
    .eq("id", id);
  if (error) throw new Error(error.message);
  const session = await getSession();
  await logEventStrict({
    action: "chapter.submission_processing_changed",
    entityType: "chapter",
    entityId: id,
    actorId: session!.user.id,
    actorType: "admin",
    delta: { reliable_submissions: form.get("enabled") === "true" },
  });
  revalidatePath("/admin/submission-processing");
}
export async function reviewRepositoryCapture(form: FormData) {
  const denied = await requireAdminAction();
  if (denied) throw new Error(denied);
  const id = String(form.get("repositoryId") ?? "");
  const action = String(form.get("action") ?? "");
  const reason = String(form.get("reason") ?? "").trim();
  if (
    !/^[a-f0-9-]{36}$/i.test(id) ||
    !["retry", "approve", "reject"].includes(action) ||
    reason.length < 5 ||
    reason.length > 1000
  )
    throw new Error("Repository, action and a reason are required");
  const db = createAdminClient();
  const { data: repository, error } = await db
    .from("submission_repositories")
    .select("*")
    .eq("id", id)
    .single();
  if (error || !repository) throw new Error("Repository not found");
  if (
    action === "approve" &&
    (!repository.frozen_sha || repository.snapshot_state !== "ready")
  )
    throw new Error("A verified frozen capture is required for approval");
  const session = await getSession();
  await logEventStrict({
    action: `submission.capture_${action}`,
    entityType: "submission_repository",
    entityId: id,
    actorId: session!.user.id,
    actorType: "admin",
    delta: { reason, frozen_sha: repository.frozen_sha },
  });
  if (action === "retry") {
    const { error: resetError } = await db
      .from("submission_jobs")
      .update({
        status: "pending",
        next_attempt_at: new Date().toISOString(),
        lease_token: null,
        lease_until: null,
      })
      .eq("repository_id", id)
      .eq("revision", repository.revision)
      .in("kind", repository.frozen_at ? ["finalize"] : ["prepare", "observe"])
      .in("status", ["review", "done", "pending"]);
    if (resetError) throw new Error("Could not schedule retry");
    await db
      .from("submission_repositories")
      .update({ repair_seconds: 300, repair_started_at: null })
      .eq("id", id);
  } else {
    const { error: updateError } = await db
      .from("submission_repositories")
      .update({
        needs_review: action === "reject",
        verification_state: action === "reject" ? "rejected" : "verified",
        last_error: action === "reject" ? reason : null,
      })
      .eq("id", id);
    if (updateError) throw new Error("Could not save decision");
    if (action === "reject")
      await db
        .from("submission_jobs")
        .update({ status: "review", lease_token: null, lease_until: null })
        .eq("repository_id", id)
        .eq("revision", repository.revision);
    else
      await db.rpc("queue_captured_review", {
        p_challenge: repository.challenge_id,
        p_team: repository.team_id,
      });
  }
  revalidatePath("/admin/submission-processing");
}
