test.describe("Reliable submission processing", () => {
  test("receipts survive unavailable GitHub and unauthorized callers cannot forge observations", async ({ page }) => {
    test.setTimeout(120000);
    const fixture = await createReliableCaptureFixture(`${RUN_ID}-receipt`);
    const admin = getAdminClient();
    const participant = await reliableCaptureParticipantClient(E2E_ACCOUNTS.president.email);
    const outsider = await reliableCaptureParticipantClient(E2E_ACCOUNTS.solo.email);
    const payload = { p_challenge: fixture.challengeId, p_team: fixture.teamIds[0], p_name: 'E2E Frozen Project', p_description: 'Receipt during an outage', p_fields: { repo: 'https://github.com/example/unavailable-repository' }, p_stack: ['TypeScript'] };
    try {
      const refused = await outsider.rpc('receive_submission',payload);
      expect(refused.error).not.toBeNull();
      const invalid = await participant.rpc('receive_submission',{ ...payload, p_fields: {} });
      expect(invalid.error).not.toBeNull();
      expect((await admin.from('submissions').select('id').eq('challenge_id',fixture.challengeId)).data).toEqual([]);
      const received = await participant.rpc('receive_submission',payload);
      expect(received.error).toBeNull();
      expect(received.data.verification).toBe('pending');
      const saved = await admin.from('submissions').select('*').eq('id',received.data.id).single();
      expect(saved.data?.project_name).toBe(payload.p_name);
      expect(saved.data?.tech_stack).toEqual(['TypeScript']);
      expect(saved.data?.processing_version).toBe(1);
      const repositories = await admin.from('submission_repositories').select('*').eq('challenge_id',fixture.challengeId);
      expect(repositories.data).toHaveLength(1);
      const r = repositories.data![0];
      const jobs = await admin.from('submission_jobs').select('*').eq('repository_id',r.id);
      expect(jobs.data?.map(j=>j.kind).sort()).toEqual(['observe','prepare']);
      const forged = await participant.from('submission_repositories').update({ observed_sha: 'a'.repeat(40) }).eq('id',r.id);
      expect(forged.error).not.toBeNull();
      const bypass = await participant.from('submissions').update({ project_name: 'Bypass' }).eq('id',received.data.id);
      expect(bypass.error).not.toBeNull();
      const stolen = await outsider.from('submission_repositories').select('*').eq('id',r.id);
      expect(stolen.data).toEqual([]);
      await loginAsParticipant(page,E2E_ACCOUNTS.president.email);
      const status = await page.request.get(`/api/submissions/repository-status?challengeId=${fixture.challengeId}&teamId=${fixture.teamIds[0]}`);
      expect(status.status()).toBe(200);
      expect((await status.json()).repositories[0].observed_sha).toBeNull();
      await loginAsAdmin(page);
      await page.goto('/admin/submission-processing');
      await expect(page.getByRole('heading',{ name: 'Submission processing', exact: true })).toBeVisible();
      await expect(page.getByText(payload.p_fields.repo,{ exact: false })).toBeVisible();
    } finally { await removeReliableCaptureFixture(fixture); }
  });

