    const { randomUUID } = await import('node:crypto');
    const sha = 'a'.repeat(40);
    try {
      for (const team of fixture.teamIds) {
        const result = await participant.rpc('receive_submission',{ p_challenge: fixture.challengeId,p_team: team,p_name: 'E2E Capacity Project',p_description: '',p_fields: { repo: 'https://github.com/example/unavailable-repository' },p_stack: [] });
        expect(result.error).toBeNull();
      }
      const repositories = await admin.from('submission_repositories').select('*').eq('challenge_id',fixture.challengeId);
      expect(repositories.data).toHaveLength(150);
      const lease = randomUUID();
      const claimed = await admin.rpc('claim_submission_job',{ p_kind: 'observe',p_lease: lease });
      expect(claimed.error).toBeNull();
      expect(claimed.data).toHaveLength(1);
      const job = claimed.data[0];
      expect(repositories.data!.some(r=>r.id===job.repository_id)).toBe(true);
      const recorded = await admin.rpc('record_submission_observation',{ p_job: job.id,p_lease: lease,p_sha: sha });
      expect(recorded.error).toBeNull(); expect(recorded.data).toBe(true);
      const expired = await admin.from('submission_jobs').update({ lease_until: new Date(Date.now()-1000).toISOString(),next_attempt_at: new Date(Date.now()-7200000).toISOString() }).eq('id',job.id);
      expect(expired.error).toBeNull();
      const oldWorker = await admin.rpc('record_submission_observation',{ p_job: job.id,p_lease: lease,p_sha: 'b'.repeat(40) });
      expect(oldWorker.data).toBe(false);
      const newLease = randomUUID();
      const reclaimed = await admin.rpc('claim_submission_job',{ p_kind: 'observe',p_lease: newLease });
      expect(reclaimed.error).toBeNull(); expect(reclaimed.data[0].id).toBe(job.id);
      const changed = await admin.rpc('record_submission_observation',{ p_job: job.id,p_lease: newLease,p_sha: 'c'.repeat(40) });
      expect(changed.error).toBeNull(); expect(changed.data).toBe(true);
      await admin.from('chapters').update({ submission_deadline: new Date(Date.now()-1).toISOString() }).eq('id',fixture.chapter.id);
      const closed = await admin.rpc('close_capture_chapter',{ p_chapter: fixture.chapter.id });
      expect(closed.error).toBeNull(); expect(closed.data).toBe(true);
      const frozen = await admin.from('submission_repositories').select('*').eq('id',job.repository_id).single();
      expect(frozen.data?.frozen_sha).toBe('c'.repeat(40));
      const late = await admin.rpc('record_submission_observation',{ p_job: job.id,p_lease: newLease,p_sha: 'd'.repeat(40) });
      expect(late.data).toBe(false);
      const rows = await admin.from('submissions').select('is_locked').eq('challenge_id',fixture.challengeId);
      expect(rows.data).toHaveLength(150); expect(rows.data!.every(s=>s.is_locked)).toBe(true);
      const state = await admin.from('chapters').select('status').eq('id',fixture.chapter.id).single();
      expect(state.data?.status).toBe('pitching');
      const pending = await admin.from('submission_jobs').select('id').eq('kind','finalize').in('repository_id',repositories.data!.map(r=>r.id));
      expect(pending.data).toHaveLength(150);
      const lateReceipt = await participant.rpc('receive_submission',{ p_challenge: fixture.challengeId,p_team: fixture.teamIds[0],p_name: 'Late',p_description: '',p_fields: { repo: 'https://github.com/example/unavailable-repository' },p_stack: [] });
      expect(lateReceipt.error).not.toBeNull();
    } finally { await removeReliableCaptureFixture(fixture); }
  });
});

