alter table public.submission_repositories add column jury_invited_users text[] not null default '{}';

-- SECURITY DEFINER avoids relying on profile-role RLS to read the allowlist.
create function public.capture_admin_reader() returns boolean language sql stable security definer
set search_path = public as $$
  select auth.uid() is not null and (
    exists(select 1 from public.profiles where id=auth.uid() and role='admin')
    or exists(select 1 from public.admin_emails ae join auth.users u on lower(ae.email)=lower(u.email) where u.id=auth.uid())
  );
$$;
revoke all on function public.capture_admin_reader() from public,anon;
grant execute on function public.capture_admin_reader() to authenticated,service_role;
create policy "Allowlisted admins read repository status" on public.submission_repositories
for select to authenticated using (public.capture_admin_reader());

create or replace function public.bind_submission_repository(p_challenge uuid, p_team uuid, p_field text, p_url text, p_branch text default '')
returns uuid language plpgsql security definer set search_path = public as $$
declare c public.challenges; f jsonb; r public.submission_repositories; normalized text;
begin
  c := public.authorize_submission_capture(p_challenge,p_team);
  select value into f from jsonb_array_elements(c.submission_fields) where value->>'key'=p_field and value->>'type'='repo';
  if f is null then raise exception 'Unknown repository field'; end if;
  if p_url is null or length(p_url)>300 or p_url !~ '^https://github[.]com/[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+/?$' then raise exception 'Invalid GitHub repository URL'; end if;
  if p_branch is null or length(p_branch)>200 or p_branch ~ '[[:cntrl:] ~^:?*\[\\]' or p_branch ~ '(^-|[.][.]|@\{|/$|[.]lock$)' then raise exception 'Invalid branch'; end if;
  normalized := regexp_replace(regexp_replace(p_url,'/$',''),'[.]git$','');
  select * into r from public.submission_repositories where challenge_id=p_challenge and team_id=p_team and field_key=p_field for update;
  if r.id is null then
    insert into public.submission_repositories(challenge_id,team_id,field_key,repo_url,branch,access_mode,entire_required)
      values(p_challenge,p_team,p_field,normalized,p_branch,coalesce(f->>'repoAccess','public'),coalesce(c.entire_required,false)) returning * into r;
  elsif r.repo_url <> normalized or (p_branch <> '' and r.branch <> p_branch) then
    update public.submission_repositories set repo_url=normalized,branch=p_branch,revision=revision+1,
      verification_state='pending',snapshot_state=case when r.repo_url=normalized and r.fork_url is not null then 'prepared' else 'pending' end,
      jury_state=case when r.repo_url=normalized then r.jury_state else 'pending' end,
      fork_url=case when r.repo_url=normalized then r.fork_url else null end,
      jury_invited_users=case when r.repo_url=normalized then r.jury_invited_users else '{}'::text[] end,
      observed_sha=null,observed_at=null,checkpoint_manifest='[]',checkpoint_observed_at=null,checkpoint_truncated=false,
      frozen_sha=null,frozen_at=null,final_ref=null,last_error=null,needs_review=false,repair_seconds=300,repair_started_at=null
      where id=r.id returning * into r;
  end if;
  update public.submission_jobs set status='done',lease_token=null,lease_until=null
    where repository_id=r.id and revision<>r.revision;
  insert into public.submission_jobs(repository_id,revision,kind) values(r.id,r.revision,'prepare') on conflict do nothing;
  insert into public.submission_jobs(repository_id,revision,kind) values(r.id,r.revision,'observe')
    on conflict(repository_id,revision,kind) do update set next_attempt_at=least(submission_jobs.next_attempt_at,now());
  return r.id;
end $$;

create or replace function public.patch_submission_repository(p_job uuid,p_lease uuid,p_patch jsonb) returns boolean
language plpgsql security definer set search_path = public as $$
declare r public.submission_repositories; j public.submission_jobs; merged public.submission_repositories;
begin
 select * into j from public.submission_jobs where id=p_job and lease_token=p_lease and status='running' and lease_until>now() for update;
 if j.id is null then return false; end if;
 select * into r from public.submission_repositories where id=j.repository_id and revision=j.revision for update;
