import type { SupabaseClient } from "@supabase/supabase-js";
import { getSettingValue, SETTING_KEYS } from "@/lib/settings";
import { CaptureGitHub } from "./github-client";
import { isDevLoginEnabled } from "@/lib/dev-login";

// Both cron and Actions must resolve the same bot from the same database.
export async function captureCredentials() {
  const [token, org, teams] = await Promise.all([
    getSettingValue(SETTING_KEYS.GITHUB_TOKEN),
    getSettingValue(SETTING_KEYS.GITHUB_ORG),
    getSettingValue("github_jury_teams"),
  ]);
  if (!token || !org || !/^[A-Za-z0-9-]+$/.test(org))
    throw new Error(
      "Configure shared GitHub settings in this database before running capture workers",
    );
  const juryTeams: Record<string, string> = teams ? JSON.parse(teams) : {};
  if (
    !juryTeams ||
    typeof juryTeams !== "object" ||
    Array.isArray(juryTeams) ||
    Object.entries(juryTeams).some(
      ([id, slug]) =>
        !/^[a-f0-9-]{36}$/i.test(id) ||
        typeof slug !== "string" ||
        !/^[A-Za-z0-9-]+$/.test(slug),
    )
  )
    throw new Error("Invalid shared GitHub jury team configuration");
  return { token, org, juryTeams };
}
export async function dispatchCaptureWorker(db: SupabaseClient, token: string) {
  const repository = process.env.GITHUB_REPO;
  if (!repository || !/^[\w.-]+\/[\w.-]+$/.test(repository))
    throw new Error("GITHUB_REPO is not configured");
  // Dispatch permission belongs to the platform repository, not private source access.
  const github = new CaptureGitHub(db, process.env.GITHUB_TOKEN || token);
  await github.json(`/repos/${repository}/dispatches`, "POST", {
    event_type: isDevLoginEnabled()
      ? "process-submission-captures-test"
      : "process-submission-captures",
  });
}
import { createAdminClient } from "../lib/supabase/admin";
import { captureCredentials } from "../lib/submission-processing/server";
import { CaptureWorker } from "../lib/submission-processing/worker";
import { transferCapturedRepository } from "../lib/submission-processing/git-transfer";

async function main() {
  const expected = process.env.CAPTURE_EXPECTED_DATABASE_URL;
  if (!expected || expected !== process.env.NEXT_PUBLIC_SUPABASE_URL)
    throw new Error("Capture worker database guard failed");
  const db = createAdminClient();
  const { token, org, juryTeams } = await captureCredentials();
  if (!token || !org)
    throw new Error("Capture worker GitHub configuration missing");
  const worker = new CaptureWorker(
    db,
    token,
    org,
    (r, heartbeat) => transferCapturedRepository(r, token, heartbeat),
    juryTeams,
  );
  const deadline = Date.now() + 20 * 60_000;
  while (Date.now() < deadline) {
    const final = await worker.runOne("finalize");
    const prepared = await worker.runOne("prepare");
    if (!final && !prepared) break;
  }
}
main().catch(() => {
  console.error(
    "Capture worker failed. Check this database’s shared GitHub settings. Pending jobs remain recoverable.",
  );
  process.exitCode = 1;
});
