/** In-memory GitHub double. Unknown endpoints fail closed; never sends HTTP. */
export class DemoGitHub {
  mode: 'healthy' | 'outage' | 'limited' = 'healthy';
  readonly forks = new Map<string, { parent: { id: number }; html_url: string; sha?: string }>();
  constructor(readonly identity: number, readonly sourceOwner: string) {}
  sha(repo: string) { return createHash('sha1').update(repo).digest('hex'); }
  async fetch(input: string | URL | Request, init?: RequestInit): Promise<Response> {
    const url = new URL(input instanceof Request ? input.url : String(input));
    const path = url.pathname;
    if (url.origin !== 'https://api.github.com') throw new Error('Demo only accepts the GitHub API');
    const json = (body: unknown, status = 200, headers = {}) => new Response(JSON.stringify(body), { status, headers: { 'content-type': 'application/json', ...headers } });
    if (path === '/user') return json({ id: this.identity });
    if (this.mode !== 'healthy') return json({ message: `Simulated GitHub ${this.mode}` }, this.mode === 'outage' ? 503 : 429, { 'retry-after': '5' });
    const match = path.match(/^\/repos\/([^/]+)\/([^/]+)(.*)$/);
    if (!match) throw new Error(`Unsupported demo endpoint: ${path}`);
    const [, owner, repo, suffix] = match;
    const key = `/repos/${owner}/${repo}`;
    if (owner === this.sourceOwner) {
      const id = parseInt(this.sha(repo).slice(0, 7), 16);
      if (!suffix) return json({ id, private: false, default_branch: 'main' });
      if (suffix === '/forks' && init?.method === 'POST') {
        const body = JSON.parse(String(init.body));
        const fullName = `${body.organization}/${body.name}`;
        this.forks.set(`/repos/${fullName}`, { parent: { id }, html_url: `https://github.com/${fullName}` });
        return json({ full_name: fullName }, 202);
      }
      if (suffix === '/git/ref/heads/main') return json({ object: { sha: this.sha(repo) } });
      if (suffix === `/git/commits/${this.sha(repo)}`) return json({ sha: this.sha(repo) });
    } else if (this.forks.has(key)) {
      const fork = this.forks.get(key)!;
      if (!suffix) return json(fork);
      if (suffix.startsWith('/git/ref/heads/ehl-final/') && fork.sha) return json({ object: { sha: fork.sha } });
    } else if (!suffix) return json({ message: 'Not Found' }, 404);
    throw new Error(`Unsupported demo endpoint: ${path}`);
  }
  capture(forkUrl: string, sha: string) {
    const fork = this.forks.get(`/repos${new URL(forkUrl).pathname}`);
    if (!fork) throw new Error('Demo fork missing');
    fork.sha = sha;
  }
}
