import type { SupabaseClient } from "@supabase/supabase-js";
import { isDevLoginEnabled } from "@/lib/dev-login";
/** Called by the existing cron, never by Submit. Idle events make no GitHub call. */
export async function dispatchPendingSnapshots(
  db: SupabaseClient,
): Promise<void> {
  const now = new Date().toISOString();
  const { count, error } = await db
    .from("submission_snapshot_jobs")
    .select("submission_id", { head: true, count: "exact" })
    .or(
      `and(status.eq.queued,next_attempt_at.lte.${now}),and(status.eq.running,lease_until.lt.${now})`,
    );
  if (error) throw new Error("Cannot inspect pending snapshots");
  if (!count) return;
  const { data: active, error: activeError } = await db
    .from("app_settings")
    .select("key")
    .eq("key", "snapshot:worker")
    .gt("expires_at", now)
    .maybeSingle();
  if (activeError) throw new Error("Cannot inspect snapshot worker lease");
  if (active) return;
  const token = process.env.GITHUB_TOKEN,
    repo = process.env.GITHUB_REPO;
  if (!token || !repo || !/^[\w.-]+\/[\w.-]+$/.test(repo))
    throw new Error("Snapshot dispatch needs GITHUB_TOKEN and GITHUB_REPO");
  const { data: locked, error: lockError } = await db.rpc(
    "try_acquire_cron_lock",
    { lock_key: "snapshot:dispatch", ttl_seconds: 300 },
  );
  if (lockError) throw new Error("Cannot acquire snapshot dispatch lock");
  if (!locked) return;
  try {
    const response = await fetch(
      `https://api.github.com/repos/${repo}/dispatches`,
      {
        method: "POST",
        headers: {
          Authorization: `Bearer ${token}`,

  );
  const remaining = response.headers.get("x-ratelimit-remaining");
  const reset = Number(response.headers.get("x-ratelimit-reset"));
  const retry = Number(response.headers.get("retry-after"));
  const limited =
    response.status === 429 ||
    (response.status === 403 &&
      (remaining === "0" || retry > 0 || /rate limit|abuse/i.test(message)));
  const delay =
    retry > 0
      ? retry
      : remaining === "0" && reset * 1000 > Date.now()
        ? Math.ceil((reset * 1000 - Date.now()) / 1000)
        : 60;
  console.error("Snapshot GitHub request failed", {
    status: response.status,
    message,
    remaining,
    reset,
    retryAfter: retry,
    requestId: response.headers.get("x-github-request-id"),
  });
  return new GitHubFailure(
    message,
    limited
      ? "rate_limit"
      : response.status >= 500
        ? "transient"
        : response.status === 401 || response.status === 403
          ? "configuration"
          : "access",
    delay,
  );
}
/** Serial REST calls, paced across worker restarts by account, never by token value. */
